import { mkdir, readFile, rm, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const repositoryRoot = join(dirname(fileURLToPath(import.meta.url)), "..")
const sourceDirectory = join(
  repositoryRoot,
  "packages/sdk/src/runtime/react/admin-list",
)
const targetDirectory = join(
  repositoryRoot,
  "packages/sdk/source/admin-list",
)
const sourceFiles = [
  "AdminList.tsx",
  "dataSources.ts",
  "index.ts",
  "preferences.ts",
  "types.ts",
]
const generatedBanner =
  "// Complete ejectable AdminList source. Generated by npm run source:admin-list.\n" +
  "// After copying this directory into an application it is fully application-owned.\n"

await rm(targetDirectory, { recursive: true, force: true })
await mkdir(targetDirectory, { recursive: true })

for (const fileName of sourceFiles) {
  const source = await readFile(join(sourceDirectory, fileName), "utf8")
  const publicOnlySource = source.replace(
    /from ["']\.\.\/\.\.\/core["']/g,
    'from "openxiangda/runtime"',
  )
  await writeFile(
    join(targetDirectory, fileName),
    `${generatedBanner}${publicOnlySource}`,
    "utf8",
  )
}

await writeFile(
  join(targetDirectory, "README.md"),
  `# AdminList 可复制源码

此目录是 \`AdminList\` 的完整、可直接复制版本。它只依赖 React、Ant Design
和 OpenXiangda 公开 SDK，不引用平台私有模块或旧列表实现。

复制到业务项目后：

1. 保留目录内文件的相对位置；
2. 从本目录的 \`index.ts\` 引入组件和类型；
3. 源码从复制时起完全由业务项目维护，不与 npm 包双向同步，也不会自动升级。

\`AdminList\` 默认不渲染页面标题、列表标题、说明或面包屑，页面壳负责这些内容。
`,
  "utf8",
)
